import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>পোর্টালের সীমা 73KB বা 137KB-এর মতো অদ্ভুত সংখ্যা? সাধারণ কমপ্রেসর শুধু 50KB, 100KB বা 200KB দেয়৤ নির্দিষ্ট আকারের জন্য টার্গেট কমপ্রেসর দরকার৤</p>\n<p>টার্গেট কমপ্রেসরে আপনি যেকোনো সংখ্যা লিখতে পারেন৤ টুলটি ঠিক সেই আকারে ছবি বানিয়ে দেয়৤</p>\n<p>এই গাইডে আপনি জানবেন এটি কীভাবে কাজ করে, কখন ব্যবহার করবেন, আর কীভাবে অসম্ভব লক্ষ্য সামলাবেন৤</p>\n<h2 id=\"what-is-target-compression\">টার্গেট কমপ্রেশন কী</h2>\n<p>টার্গেট কমপ্রেশন মানে ছবিকে আপনার লেখা নির্দিষ্ট আকারে নিয়ে আসা৤ যেকোনো KB বা MB সংখ্যা লেখা যায়৤</p>\n<p>সাধারণ টুলে নির্দিষ্ট আকার দেওয়া থাকে৤ টার্গেট টুলে আপনি নিজেই সংখ্যাটি ঠিক করেন৤</p>\n<p>এটি ফরমের অদ্ভুত সীমার জন্য সবচেয়ে ভালো৤ পোর্টাল যা চায়, ঠিক তাই বানানো যায়৤</p>\n<h2 id=\"how-it-works\">এটি কীভাবে কাজ করে</h2>\n<p><a href=\"/bn/target-file-size-compressor\">টার্গেট ফাইল সাইজ কমপ্রেসর</a> খুলে লক্ষ্য সংখ্যাটি লিখুন, যেমন 73KB৤</p>\n<p>তারপর ছবি আপলোড করুন৤ টুলটি বাইনারি সার্চ চালিয়ে এমন কোয়ালিটি খোঁজে যা লক্ষ্যের নিচে থাকে৤</p>\n<p>কোয়ালিটি দিয়ে না হলে টুল মাপ কমায়৤ এই দুই ধাপে বেশিরভাগ ছবি লক্ষ্যে পৌঁছায়৤</p>\n<h2 id=\"kb-vs-mb\">KB বনাম MB</h2>\n<p>KB ছোট একক, MB বড় একক৤ 1MB মানে 1024KB৤</p>\n<p>ফরমের সীমা সাধারণত KB-তে দেওয়া হয়৤ ওয়েবসাইটের সীমা MB-তেও হতে পারে৤</p>\n<p>সংখ্যা লেখার সময় একক দেখে নিন৤ 1MB লিখতে গিয়ে 1KB লিখলে ছবি অকেজো হয়ে যাবে৤</p>\n<h2 id=\"when-to-use-custom\">কখন কাস্টম লক্ষ্য ব্যবহার করবেন</h2>\n<p>পোর্টালের সীমা সাধারণ আকারের বাইরে হলে কাস্টম লক্ষ্য ব্যবহার করুন৤ যেমন 73KB বা 137KB৤</p>\n<p>ইমেইলের সীমা মেলাতেও কাস্টম লক্ষ্য ভালো৤ মোট আকার ঠিক রাখতে প্রতিটি ছবির লক্ষ্য ঠিক করা যায়৤</p>\n<p>তবে সাধারণ কাজে সাধারণ টুলই যথেষ্ট৤ 100KB বা 200KB-তে কাস্টম লক্ষ্যের দরকার নেই৤</p>\n<p>কাস্টম টার্গেট সবচেয়ে কাজে লাগে যখন পোর্টালের সীমা অস্বাভাবিক হয়৤ ৭৩KB বা ১৩৭KB-এর মতো সীমা সাধারণ প্রিসেটে পাওয়া যায় না৤ কাস্টম সংখ্যা লিখে এই সীমা মেলানো যায়৤</p>\n<p>কাস্টম টার্গেট ইমেইলের সংযুক্তির জন্যও ভালো৤ পাঁচটি ছবি এক ইমেইলে পাঠাতে হলে প্রতিটি ছবি নির্দিষ্ট আকারে রাখতে হয়৤ কাস্টম টার্গেটে হিসাব মেলানো সহজ হয়৤</p>\n<p>কাস্টম টার্গেট ব্যবহার করার আগে ছবির মূল আকার দেখুন৤ মূল ছবি ১০MB হলে ৫০KB-তে আনা কঠিন, কিন্তু ৫০০KB-তে আনা সহজ৤ অসম্ভব লক্ষ্য বেছে নিলে সময় নষ্ট হয়৤</p>\n<p>কাস্টম টার্গেটে MB-তেও সংখ্যা লেখা যায়৤ ১.৫MB-এর মতো লক্ষ্য লিখলে টুলটি সেই আকারে ছবি তৈরি করে৤ দশমিক সংখ্যা লিখতে ভুল করবেন না৤</p>\n<p>কাস্টম টার্গেট বারবার ব্যবহার করলে সেটিংটি মনে রাখুন৤ একই পোর্টালে বারবার আবেদন করলে একই সংখ্যা লাগে৤ সংখ্যাটি নোট করে রাখলে প্রতিবার টাইপ করতে হয় না৤</p>\n<p>কাস্টম টার্গেটে ছবির মাপ কমানোর অনুমতি দিন৤ মাপ কমালে আকার দ্রুত কমে, আর টুলটি লক্ষ্য সহজে পায়৤ পোর্টালের মাপের নিয়ম থাকলে অবশ্য মাপ কমানো যাবে না৤</p>\n<p>কাস্টম টার্গেট ব্যবহার করার সময় প্রিভিউ দেখুন৤ লক্ষ্য মিললেও ছবি অস্পষ্ট হতে পারে৤ প্রিভিউতে ছবি পরিষ্কার না লাগলে লক্ষ্য একটু বাড়িয়ে আবার চালান৤</p>\n<p>কাস্টম টার্গেট দলের কাজে ব্যবহার করলে সংখ্যাটি সবাইকে জানিয়ে দিন৤ সবাই একই সংখ্যা ব্যবহার করলে ছবির আকার একই থাকে৤ ভিন্ন সংখ্যায় ছবির মান ভিন্ন হয়৤</p>\n<p>কাস্টম টার্গেট শুধু সংখ্যা নয়, এটি একটি পরিকল্পনা৤ লক্ষ্য ঠিক করার আগে ছবিটি কোথায় ব্যবহার হবে তা ভাবুন৤ সঠিক লক্ষ্য ছবির মান আর আকারের ভারসাম্য দেয়৤</p>\n<h2 id=\"binary-search-explained\">বাইনারি সার্চ, সহজ ভাষায়</h2>\n<p>বাইনারি সার্চ মানে কোয়ালিটির পরিসর অর্ধেক করে খোঁজা৤ প্রতিটি পরীক্ষায় পরিসর ছোট হয়৤</p>\n<p>এটাকে 1 থেকে 100-এর মধ্যে সংখ্যা খোঁজার মতো ভাবুন৤ কয়েকটি পরীক্ষায় সঠিক সংখ্যা মিলে যায়৤</p>\n<p>এতে আপনার ছবির জন্য সেরা কোয়ালিটি মেলে৤ গোল সংখ্যার চেয়ে সঠিক সংখ্যা ভালো৤</p>\n<h2 id=\"dimension-scaling\">মাপ কমানো কীভাবে কাজ করে</h2>\n<p>কোয়ালিটি দিয়ে লক্ষ্য না মিললে টুল মাপ ধাপে ধাপে কমায়৤ প্রতিটি ধাপে ফাইল ছোট হয়৤</p>\n<p>মাপ কমলেও ছবি দেখতে ভালো থাকে, কারণ ছোট মাপে কম বাজেটেও পরিষ্কার ফল মেলে৤</p>\n<p>পোর্টাল নির্দিষ্ট মাপ চাইলে টুল মাপ কমাবে না৤ তখন ফরম্যাট বদলে বা ক্রপ করে লক্ষ্য মেলাতে হয়৤</p>\n<h2 id=\"impossible-targets\">অসম্ভব লক্ষ্য সামলানো</h2>\n<p>কিছু লক্ষ্য অসম্ভব৤ যেমন 10KB-তে বিস্তারিত গ্রুপ ছবি করা যায় না৤</p>\n<p>লক্ষ্য অসম্ভব হলে টুল জানিয়ে দেয়৤ এটি সততার সঙ্গে বলে লক্ষ্য মেলেনি৤</p>\n<p>তখন ফরম্যাট বদলান, ক্রপ করুন বা মাপ কমান৤ তাতেও না হলে পোর্টালের নিয়ম আবার পড়ুন৤</p>\n<h2 id=\"formats-custom\">কাস্টম লক্ষ্যে ফরম্যাট</h2>\n<p>ছবির জন্য JPG সবচেয়ে নির্ভরযোগ্য৤ সব পোর্টাল এটি নেয়৤</p>\n<p>WebP একই আকারে JPG-এর চেয়ে সামান্য বেশি বিবরণ ধরে রাখে৤ পোর্টাল নিলে WebP ব্যবহার করুন৤</p>\n<p>PNG ছবির ক্ষেত্রে কাস্টম লক্ষ্যেও পিছিয়ে থাকে৤ লোগো বা লেখার ছবি ছাড়া PNG এড়িয়ে চলুন৤</p>\n<p>কাস্টম লক্ষ্যে ফরম্যাট বেছে নেওয়ার সময় ছবির ধরন দেখুন৤ ছবিতে মানুষ থাকলে JPG ভালো৤ লেখা থাকলে WebP ভালো৤ ভুল ফরম্যাটে লক্ষ্য মেলা কঠিন হয়৤</p>\n<p>কাস্টম লক্ষ্যে WebP সবচেয়ে ছোট ফাইল দেয়৤ তবে পোর্টাল WebP নাও নিতে পারে৤ পোর্টালের নিয়ম দেখে ফরম্যাট বেছে নিন৤</p>\n<p>কাস্টম লক্ষ্যে PNG থেকে JPG-তে গেলে ফাইল অনেক ছোট হয়৤ PNG ছবি কাস্টম লক্ষ্যে আনতে JPG-তে বদলান৤ স্বচ্ছতা দরকার হলে PNG-তেই থাকুন৤</p>\n<p>কাস্টম লক্ষ্যে ফরম্যাট বদলানোর পর মান দেখুন৤ JPG-তে লেখা কিছুটা নরম হয়৤ লেখা বেশি থাকলে WebP চেষ্টা করুন৤</p>\n<p>কাস্টম লক্ষ্যে HEIC ছবির আউটপুট JPG বেছে নিন৤ আইফোনের ছবি সরাসরি JPG-তে আসে৤ আলাদা কনভার্টের ধাপ দরকার হয় না৤</p>\n<p>কাস্টম লক্ষ্যে ফরম্যাটের পছন্দ পরে বদলানো যায়৤ মূল ফাইল থাকলে নতুন ফরম্যাটে আবার চালানো যায়৤ তাই পরীক্ষা করতে ভয় পাবেন না৤</p>\n<p>কাস্টম লক্ষ্যে একই ছবি দুটি ফরম্যাটে চালিয়ে তুলনা করুন৤ কোন ফরম্যাটে ছবি পরিষ্কার দেখায় তা চোখে দেখে বুঝুন৤ সংখ্যার চেয়ে চোখের বিচার ভালো৤</p>\n<p>কাস্টম লক্ষ্যে ফরম্যাটের সঙ্গে মাপের সম্পর্ক আছে৤ PNG-তে মাপ কমালে ফাইল দ্রুত ছোট হয়৤ JPG-তে কোয়ালিটি কমালে ফাইল ছোট হয়৤</p>\n<p>কাস্টম লক্ষ্যে ফরম্যাট বেছে নেওয়ার সময় ভবিষ্যতের ব্যবহার ভাবুন৤ ছবিটি পরে সম্পাদনা করার পরিকল্পনা থাকলে PNG রাখুন৤ শুধু পাঠানোর জন্য JPG যথেষ্ট৤</p>\n<h2 id=\"batch-custom\">কাস্টম লক্ষ্যে ব্যাচ করা</h2>\n<p>একাধিক ছবি একই লক্ষ্যে করতে হলে ব্যাচ টুল ব্যবহার করুন৤ প্রতিটি ছবিতে আলাদা সার্চ চলে৤</p>\n<p>ব্যাচের আগে একটি ছবি পরীক্ষা করুন৤ লক্ষ্য ঠিক আছে কি না দেখুন৤</p>\n<p>ব্যাচ শেষে প্রতিটি ছবি দেখুন৤ কোনো ছবি লক্ষ্য না মিললে আলাদাভাবে আবার করুন৤</p>\n<h2 id=\"common-mistakes\">সাধারণ ভুলগুলো</h2>\n<p>সবচেয়ে বড় ভুল হলো একক গুলিয়ে ফেলা৤ KB লিখতে গিয়ে MB লিখলে ছবি অকেজো হয়৤</p>\n<p>আরেকটি ভুল হলো স্ক্রিনশট দিয়ে শুরু করা৤ স্ক্রিনশটে বাড়তি শব্দ থাকে যা বাজেট নষ্ট করে৤</p>\n<p>কমপ্রেস করা ফাইল আবার কমপ্রেস করবেন না৤ প্রতিবার কোয়ালিটি কমে৤</p>\n<h2 id=\"privacy-custom\">গোপনীয়তা</h2>\n<p>টার্গেট কমপ্রেশনও আপনার ডিভাইসেই হয়৤ ছবি কোনো সার্ভারে আপলোড হয় না৤</p>\n<p>টুলটি ছবি থেকে GPS ট্যাগ মুছে দেয়৤ এতে শেয়ার করা ছবিতে অবস্থানের তথ্য থাকে না৤</p>\n<p>তবুও ব্যক্তিগত ছবি অপরিচিত টুলে দেবেন না৤ এই টুলে সব প্রক্রিয়া স্থানীয়ভাবে হয়৤</p>\n<h2 id=\"unit-mistakes\">এককের ভুল এড়ানো</h2>\n<p>লক্ষ্য লেখার সময় একক দেখুন৤ 100KB আর 100MB-এর মধ্যে অনেক পার্থক্য৤</p>\n<p>পোর্টালের নিয়মে একক কী লেখা আছে তা দেখুন৤ KB না MB, তা নিশ্চিত করুন৤</p>\n<p>সন্দেহ থাকলে ছোট এককে লিখুন৤ 0.1MB-এর বদলে 100KB লিখলে ভুল কম হয়৤</p>\n<p>একক ভুল করলে ফাইল দশ গুণ বড় বা ছোট হয়৤ KB লিখতে গিয়ে MB লিখলে ফাইল অনেক বড় হয়৤ MB লিখতে গিয়ে KB লিখলে ছবি নষ্ট হয়৤ একক দেখে সংখ্যা লিখুন৤</p>\n<p>একক ভুল এড়াতে সংখ্যার পাশে একক লিখুন৤ ৫০০KB লিখলে বোঝা যায় একক KB৤ শুধু ৫০০ লিখলে একক বোঝা যায় না৤</p>\n<p>একক ভুল হলে ফলাফল দেখে ধরা পড়ে৤ ফাইল অস্বাভাবিক বড় বা ছোট হলে একক ভুল হয়েছে৤ ফল দেখে একক পরীক্ষা করুন৤</p>\n<p>একক ভুল এড়াতে টুলের এককের অপশন দেখুন৤ টুলে KB আর MB-এর আলাদা বোতাম থাকে৤ সঠিক বোতামে ক্লিক করুন৤</p>\n<p>একক ভুল হলে পোর্টাল ফাইল ফিরিয়ে দেয়৤ পোর্টালের সীমা KB-তে থাকলে MB-তে ফাইল পাঠালে ফরম বাতিল হয়৤ সীমার একক দেখুন৤</p>\n<p>একক ভুল এড়াতে সংখ্যা টাইপ করার পর আবার পড়ুন৤ টাইপের ভুলে একক বদলে যেতে পারে৤ পাঠানোর আগে সংখ্যা আর একক পরীক্ষা করুন৤</p>\n<p>একক ভুল হলে মূল ফাইল থেকে আবার করুন৤ ভুল এককে তৈরি ফাইল ব্যবহার করবেন না৤ মূল থেকে সঠিক এককে আবার করুন৤</p>\n<p>একক ভুল এড়াতে দলের সবাইকে এককের নিয়ম জানান৤ সবাই একই একক ব্যবহার করলে ভুল কমে৤ নিয়মটি লিখে রাখুন৤</p>\n<p>একক ভুল শুধু সংখ্যার ভুল নয়, এটি ধারণার ভুল৤ KB আর MB-এর পার্থক্য বুঝুন৤ ১MB মানে ১০০০KB-এর কাছাকাছি৤</p>\n<h2 id=\"target-for-email\">ইমেইলের জন্য লক্ষ্য ঠিক করা</h2>\n<p>ইমেইলের মোট সীমা দেখুন৤ যেমন 25MB সীমা থাকলে দশটি ছবির প্রতিটি 2MB-এর নিচে রাখুন৤</p>\n<p>প্রতিটি ছবির লক্ষ্য আলাদাভাবে ঠিক করুন৤ গুরুত্বপূর্ণ ছবিতে বেশি বাজেট দিন৤</p>\n<p>ইমেইলে ছবি পাঠানোর আগে মোট আকার দেখুন৤ সীমার বেশি হলে লক্ষ্য কমান৤</p>\n<h2 id=\"target-for-print-prep\">ছাপার প্রস্তুতিতে লক্ষ্য</h2>\n<p>ছাপার জন্য বড় লক্ষ্য রাখুন৤ ছোট লক্ষ্যে ছাপা ঝাপসা হয়৤</p>\n<p>ছাপার মাপ জেনে নিন৤ মাপ অনুযায়ী লক্ষ্য ঠিক করুন৤</p>\n<p>ছাপার কাজে মূল ফাইল ব্যবহার করাই সবচেয়ে ভালো৤ কমপ্রেস করা ফাইল শুধু তখনই ব্যবহার করুন যখন মূল ফাইল নেই৤</p>\n<h2 id=\"comparing-targets\">লক্ষ্য তুলনা করা</h2>\n<p>একই ছবি দুটি লক্ষ্যে বানিয়ে তুলনা করুন৤ কোনটি আপনার কাজের জন্য যথেষ্ট, তা বুঝতে পারবেন৤</p>\n<p>তুলনার সময় ছবিটি যে আকারে দেখানো হবে, সেই আকারে দেখুন৤</p>\n<p>যে লক্ষ্যে ছবি পরিষ্কার দেখায় সেটি বেছে নিন৤ তার চেয়ে বড় লক্ষ্যের দরকার নেই৤</p>\n<h2 id=\"saving-presets\">প্রিসেট সংরক্ষণ করা</h2>\n<p>একই লক্ষ্য বারবার ব্যবহার হলে তা লিখে রাখুন৤ যেমন পোর্টালের 73KB লক্ষ্য৤</p>\n<p>লক্ষ্যগুলো একটি নোটে রাখুন৤ পরের আবেদনে একই লক্ষ্য ব্যবহার করা যায়৤</p>\n<p>লক্ষ্য বদলালে নোট আপডেট করুন৤ পুরোনো লক্ষ্য ব্যবহার করলে ভুল হতে পারে৤</p>\n<p>প্রিসেট সংরক্ষণ করার সময় তার নামে লক্ষ্য লিখুন৤ নামে লক্ষ্য থাকলে পরে চিনতে সুবিধা হয়৤ 50kb-portal-এর মতো নাম দিন৤</p>\n<p>প্রিসেট সংরক্ষণ করার সময় তার বিবরণ লিখুন৤ বিবরণে ফরম্যাট আর কোয়ালিটি লিখুন৤ বিবরণ থাকলে অন্যরা প্রিসেট বুঝতে পারেন৤</p>\n<p>প্রিসেট সংরক্ষণ করার পর তা পরীক্ষা করুন৤ সংরক্ষিত প্রিসেটে একটি ছবি চালিয়ে দেখুন৤ ফল ভালো হলে প্রিসেট ঠিক আছে৤</p>\n<p>প্রিসেট সংরক্ষণ করার সময় দলের সঙ্গে শেয়ার করুন৤ সবাই একই প্রিসেট ব্যবহার করলে ছবির মান একই থাকে৤</p>\n<p>প্রিসেট সংরক্ষণ করার পর পুরোনো প্রিসেট মুছে ফেলুন৤ পুরোনো প্রিসেট রাখলে গোলমাল হয়৤ শুধু ভালো প্রিসেট রাখুন৤</p>\n<p>প্রিসেট সংরক্ষণ করার সময় ব্রাউজারের ডেটা মুছবেন না৤ ব্রাউজারের ডেটা মুছলে সংরক্ষিত প্রিসেট হারিয়ে যায়৤ প্রিসেটের তথ্য নোট করে রাখুন৤</p>\n<p>প্রিসেট সংরক্ষণ করার সময় ভিন্ন পোর্টালের জন্য ভিন্ন প্রিসেট রাখুন৤ প্রতিটি পোর্টালের সীমা ভিন্ন হয়৤ ভিন্ন সীমার জন্য ভিন্ন প্রিসেট দরকার৤</p>\n<p>প্রিসেট সংরক্ষণ করার পর তা নিয়মিত আপডেট করুন৤ নতুন ছবির ধরন বদলে গেলে প্রিসেটও বদলাতে হতে পারে৤</p>\n<p>প্রিসেট সংরক্ষণ করা সময় বাঁচায়৤ প্রতিবার সেটিং না সাজিয়ে সংরক্ষিত প্রিসেট ব্যবহার করুন৤ সময় বাঁচলে কাজ দ্রুত হয়৤</p>\n<h2 id=\"accessibility-custom\">অ্যাক্সেসিবিলিটি</h2>\n<p>ছবি এত ছোট করবেন না যে লেখা পড়া যায় না৤ লেখা থাকা ছবিতে মান বেশি রাখুন৤</p>\n<p>ওয়েবসাইটে ছবি দিলে alt টেক্সট যোগ করুন৤ এতে স্ক্রিন রিডার ব্যবহারকারীরা ছবি বুঝতে পারে৤</p>\n<p>দ্রুত লোড হওয়া পাতা সবার জন্য ভালো৤ ধীর সংযোগ ব্যবহারকারীরাও সহজে পাতা দেখতে পারে৤</p>\n<p>নির্দিষ্ট KB-তে করার পদ্ধতি জানতে পড়ুন <a href=\"/bn/blog/image-exact-kb-te-compress-kivabe-korben\">ছবি নির্দিষ্ট KB-তে কমপ্রেস করবেন কীভাবে</a> আর সার্চের পেছনের বিজ্ঞান জানতে দেখুন <a href=\"/bn/blog/exact-kb-target-binary-quality-search\">বাইনারি কোয়ালিটি সার্চ</a>৤ সাধারণ আকারের জন্য <a href=\"/bn/image-100kb-te-compress-korun\">100KB কমপ্রেসর</a> আর <a href=\"/bn/image-200kb-te-compress-korun\">200KB কমপ্রেসর</a> ব্যবহার করুন৤</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"টার্গেট কমপ্রেসরে যেকোনো সংখ্যা লেখা যায়?","answer":"হ্যাঁ৤ যেকোনো KB বা MB সংখ্যা লেখা যায়, যেমন 73KB বা 1.5MB৤ টুলটি বাইনারি সার্চ চালিয়ে সেই আকারের নিচে সবচেয়ে পরিষ্কার ছবি বানায়৤ তবে কিছু লক্ষ্য অসম্ভব হতে পারে, যেমন 10KB-তে বিস্তারিত গ্রুপ ছবি৤"},{"question":"KB আর MB গুলিয়ে গেলে কী হয়?","answer":"100KB লিখতে গিয়ে 100MB লিখলে ছবি প্রায় কমপ্রেসই হয় না৤ আর 1MB লিখতে গিয়ে 1KB লিখলে ছবি অকেজো হয়ে যায়৤ লক্ষ্য লেখার সময় একক দেখে নিন৤ সন্দেহ থাকলে KB-তে লিখুন৤"},{"question":"লক্ষ্য অসম্ভব হলে টুল কী করে?","answer":"টুল সততার সঙ্গে জানায় লক্ষ্য মেলেনি৤ তখন ফরম্যাট বদলান, ছবি টাইট ক্রপ করুন বা মাপ কমান৤ তাতেও না হলে পোর্টালের নিয়ম আবার পড়ুন, হয়তো অন্য ফরম্যাট গ্রহণ করা হয়৤"},{"question":"কাস্টম লক্ষ্যে কোন ফরম্যাট সবচেয়ে ভালো?","answer":"ছবির জন্য JPG সবচেয়ে নির্ভরযোগ্য৤ WebP একই আকারে একটু বেশি বিবরণ ধরে রাখে, তবে সব পোর্টাল এটি নেয় না৤ PNG ছবির ক্ষেত্রে এড়িয়ে চলুন, লোগো বা লেখার জন্য রাখুন৤"},{"question":"একাধিক ছবি একই লক্ষ্যে করা যায়?","answer":"হ্যাঁ৤ ব্যাচ টুলে একই লক্ষ্য দিয়ে অনেক ছবি করা যায়৤ প্রতিটি ছবিতে আলাদা সার্চ চলে৤ ব্যাচের আগে একটি ছবি পরীক্ষা করুন, আর শেষে প্রতিটি ছবি দেখে নিন৤"},{"question":"টার্গেট কমপ্রেশন কি নিরাপদ?","answer":"হ্যাঁ৤ সব কাজ আপনার ডিভাইসেই হয়, ছবি কোনো সার্ভারে যায় না৤ টুলটি GPS ট্যাগও মুছে দেয়৤ পরিচয়পত্রের ছবির জন্যও এটি নিরাপদ৤"}];
